import React, { useEffect, useMemo, useState } from 'react';
import { createRoot } from 'react-dom/client';
import './styles.css';

const API = (import.meta.env.VITE_API_URL || (import.meta.env.PROD ? '' : 'http://127.0.0.1:8000'));
const STATUS = {draft:'Draft', checked:'Checked', submitted:'In review', approved:'Approved', changes_requested:'Changes requested'};
const ROLE_DESC = {creator:'Create, check and revise content', reviewer:'Review submissions and approve content', admin:'Manage brand rules, facts and terminology'};

async function request(path, {token, ...options} = {}) {
  const headers = new Headers(options.headers || {});
  if (token) headers.set('Authorization', `Bearer ${token}`);
  if (options.body && !(options.body instanceof FormData) && typeof options.body !== 'string') {
    headers.set('Content-Type', 'application/json'); options.body = JSON.stringify(options.body);
  }
  const response = await fetch(`${API}${path}`, {...options, headers});
  const raw = await response.text();
  let data; try { data = raw ? JSON.parse(raw) : null; } catch { data = raw; }
  if (!response.ok) throw new Error(data?.detail || data?.message || `Request failed (${response.status})`);
  return data;
}
