function Pill({children, tone=''}) { return <span className={`pill ${tone}`}>{children}</span> }
function Button({children, onClick, variant='primary', disabled=false, type='button', small=false}) { return <button type={type} disabled={disabled} onClick={onClick} className={`btn ${variant} ${small?'small':''}`}>{children}</button> }
function Field({label, children, hint}) { return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label> }
function Empty({title, text, action}) { return <div className="empty"><div className="empty-mark"><Icon name="file"/></div><h3>{title}</h3><p>{text}</p>{action}</div> }

