 async function addSource(kind,e){e.preventDefault();try{let body,path;if(kind==='guideline'){path='/guidelines';body={code:sourceForm.code,title:sourceForm.title,content:sourceForm.content,rule_type:sourceForm.rule_type,keywords:sourceForm.keywords.split(',').map(x=>x.trim()).filter(Boolean),fact_category:sourceForm.fact_category||null}}else if(kind==='fact'){path='/facts';body={code:sourceForm.code,statement:sourceForm.statement,category:sourceForm.category||'general',source_url:sourceForm.source_url||null,expires_at:sourceForm.expires_at||null}}else{path='/terms';body={code:sourceForm.code,approved_term:sourceForm.approved_term,banned_variants:sourceForm.banned_variants.split(',').map(x=>x.trim()).filter(Boolean),note:sourceForm.note||null}}const isEditing=editingSourceId?.kind===kind;if(isEditing)path+=`/${editingSourceId.id}`;await call(path,{method:isEditing?'PUT':'POST',body});setSourceForm({...sourceForm,code:'',title:'',content:'',keywords:'',statement:'',source_url:'',expires_at:'',approved_term:'',banned_variants:'',note:''});setEditingSourceId(null);await loadBase();notify(`${kind[0].toUpperCase()+kind.slice(1)} ${isEditing?'updated':'added'}`)}catch(e){fail(e)}}
